const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Macaya National Park, Haiti. Using a central point with a buffer for the AOI.
  const aoi = ee.Geometry.Point([-74.00, 18.06]).buffer(10000); // 10 km buffer

  // Define scale for area calculation. Hansen data is ~30m resolution,
  // but for national park scale and to avoid timeout, using 100m.
  const scale = 100;

  // 2. Data Acquisition & Check
  const gfc = ee.Image('UMD/hansen/global_forest_change_v1_12');

  // Define forest as tree cover >= 30% in the year 2000.
  const treeCoverThreshold = 30;
  const forest2000 = gfc.select('treecover2000').gte(treeCoverThreshold);

  // Calculate pixel area in square meters.
  const pixelArea = ee.Image.pixelArea();

  // Define a masked loss area for the first period (2000-2015)
  // Loss year is 1-22, corresponding to 2001-2022.
  // So, loss from 2000 to 2015 means lossyear between 1 (2001) and 15 (2015).
  const loss2000_2015 = gfc.select('lossyear')
    .updateMask(forest2000) // Only consider loss from areas that were forest in 2000
    .gte(1) // Loss must have occurred
    .and(gfc.select('lossyear').lte(15)); // Loss up to year 2015 (inclusive)

  // Define a masked loss area for the second period (2015-2022)
  // Loss year between 16 (2016) and 22 (2022).
  const loss2015_2022 = gfc.select('lossyear')
    .updateMask(forest2000) // Only consider loss from areas that were forest in 2000
    .gte(16) // Loss from year 2016 (inclusive)
    .and(gfc.select('lossyear').lte(22)); // Loss up to year 2022 (inclusive)

  // Calculate the area of forest loss for each period.
  // Multiply the binary loss mask by pixel area and sum within the AOI.
  const lossArea2000_2015 = loss2000_2015.multiply(pixelArea)
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    }).get('lossyear');

  const lossArea2015_2022 = loss2015_2022.multiply(pixelArea)
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    }).get('lossyear');

  // Fetch results
  let area1 = await lossArea2000_2015.getInfo();
  let area2 = await lossArea2015_2022.getInfo();

  // 5. Validation & Final Answer
  if (area1 === null || isNaN(area1) || area2 === null || isNaN(area2)) {
    console.log("Calculation failure for forest loss area.");
    console.log("C3");
    return;
  }

  // Convert to square kilometers for readability
  area1 = area1 / 1e6;
  area2 = area2 / 1e6;

  // Check if there are valid pixels (loss areas are non-zero)
  if (area1 === 0 && area2 === 0) {
    console.log("No valid forest loss pixels found for either period within the AOI.");
    console.log(`2000-2015 Forest Loss (km^2): ${area1.toFixed(2)}`);
    console.log(`2015-2022 Forest Loss (km^2): ${area2.toFixed(2)}`);
    console.log("C2");
    return;
  }

  console.log(`Forest Loss 2000-2015 (km^2): ${area1.toFixed(2)}`);
  console.log(`Forest Loss 2015-2022 (km^2): ${area2.toFixed(2)}`);

  if (area2 > area1) {
    console.log("A"); // Yes, forest loss from 2015-2022 is larger.
  } else {
    console.log("B"); // No, forest loss from 2015-2022 is not larger.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
